import{_ as r,a0 as o,w as l,s as c,ao as t,I as i,x as s,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Apache Kafka：為“無縫系統”提供異步消息支持 | LCTT x X-CMD","titleTemplate":false,"description":"Apache Kafka：為“無縫系統”提供異步消息支持 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Apache Kafka：為“無縫系統”提供異步消息支持 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Apache Kafka：為“無縫系統”提供異步消息支持 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20211102 Apache Kafka- Asynchronous Messaging for Seamless Systems","title":"Apache Kafka：為“無縫系統”提供異步消息支持","tag":"202206","desc":""},"relativePath":"202206/20211102 Apache Kafka- Asynchronous Messaging for Seamless Systems.md","filePath":"[post].md"}'),d={name:"202206/20211102 Apache Kafka- Asynchronous Messaging for Seamless Systems.md"};function h(g,a,k,u,f,b){const n=o("Link");return l(),c("div",null,[a[18]||(a[18]=t('<h1 id="apache-kafka-為-無縫系統-提供異步消息支持" tabindex="-1">Apache Kafka：為“無縫系統”提供異步消息支持 <a class="header-anchor" href="#apache-kafka-為-無縫系統-提供異步消息支持" aria-label="Permalink to “Apache Kafka：為“無縫系統”提供異步消息支持”">​</a></h1><blockquote><p>Apache Kafka 是最流行的開源消息代理之一。它已經成為了大數據操作的重要組成部分，你能夠在幾乎所有的微服務環境中找到它。本文對 Apache Kafka 進行了簡要介紹，並提供了一個案例來展示它的使用方式。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202206/29/094326fbo6zzsrxiava661.jpg" alt=""></p><p>你有沒有想過，電子商務平台是如何在處理巨大的流量時，做到不會卡頓的呢？有沒有想過，OTT 平台是如何在同時向數百萬用户交付內容時，做到平穩運行的呢？其實，關鍵就在於它們的分佈式架構。</p><p>採用分佈式架構設計的系統由多個功能組件組成。這些功能組件通常分佈在多個機器上，它們通過網絡，異步地交換消息，從而實現相互協作。正是由於異步消息的存在，組件之間才能實現可伸縮、無阻塞的通信，整個系統才能夠平穩運行。</p><h3 id="異步消息" tabindex="-1">異步消息 <a class="header-anchor" href="#異步消息" aria-label="Permalink to “異步消息”">​</a></h3><p>異步消息的常見特性有：</p><ul><li>消息的<ruby>生產者<rt>producer</rt></ruby>和<ruby>消費者<rt>consumer</rt></ruby>都不知道彼此的存在。它們在不知道對方的情況下，加入和離開系統。</li><li>消息<ruby>代理<rt>broker</rt></ruby>充當了生產者和消費者之間的中介。</li><li>生產者把每條消息，都與一個“<ruby>主題<rt>topic</rt></ruby>”相關聯。主題是一個簡單的字符串。</li><li>生產者可以在多個主題上發送消息，不同的生產者也可以在同一主題上發送消息。</li><li>消費者向代理訂閲一個或多個主題的消息。</li><li>生產者只將消息發送給代理，而不發送給消費者。</li><li>代理會把消息發送給訂閲該主題的所有消費者。</li><li>代理將消息傳遞給針對該主題註冊的所有消費者。</li><li>生產者並不期望得到消費者的任何回應。換句話説，生產者和消費者不會相互阻塞。</li></ul><p>市場上的消息代理有很多，而 Apache Kafka 是其中最受歡迎的之一。</p><h3 id="apache-kafka" tabindex="-1">Apache Kafka <a class="header-anchor" href="#apache-kafka" aria-label="Permalink to “Apache Kafka”">​</a></h3><p>Apache Kafka 是一個支持流式處理的、開源的分佈式消息系統，它由 Apache 軟件基金會開發。在架構上，它是多個代理組成的集羣，這些代理間通過 Apache ZooKeeper 服務來協調。在接收、持久化和發送消息時，這些代理分擔集羣上的負載。</p><h4 id="分區" tabindex="-1">分區 <a class="header-anchor" href="#分區" aria-label="Permalink to “分區”">​</a></h4><p>Kafka 將消息寫入稱為“<ruby>分區<rt>partition</rt></ruby>”的桶中。一個特定分區只保存一個主題上的消息。例如，Kafka 會把 <code>heartbeats</code> 主題上的消息寫入名為 <code>heartbeats-0</code> 的分區（假設它是個單分區主題），這個過程和生產者無關。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2021/09/Figure-1-Asynchronous-messaging.jpg" alt="圖 1：異步消息"></p><p>不過，為了利用 Kafka 集羣所提供的並行處理能力，管理員通常會為指定主題創建多個分區。舉個例子，假設管理員為 <code>heartbeats</code> 主題創建了三個分區，Kafka 會將它們分別命名為 <code>heartbeats-0</code>、<code>heartbeats-1</code> 和 <code>heartbeats-2</code>。Kafka 會以某種方式，把消息分配到這三個分區中，並使它們均勻分佈。</p><p>還有另一種可能的情況，生產者將每條消息與一個<ruby>消息鍵<rt>key</rt></ruby>相關聯。例如，同樣都是在 <code>heartbeats</code> 主題上發送消息，有個組件使用 <code>C1</code> 作為消息鍵，另一個則使用 <code>C2</code>。在這種情況下，Kafka 會確保，在一個主題中，帶有相同消息鍵的消息，總是會被寫入到同一個分區。不過，在一個分區中，消息的消息鍵卻不一定相同。下面的圖 2 顯示了消息在不同分區中的一種可能分佈。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2021/09/Figure-2-Message-distribution-among-the-partitions.jpg" alt="圖 2：消息在不同分區中的分佈"></p><h4 id="領導者和同步副本" tabindex="-1">領導者和同步副本 <a class="header-anchor" href="#領導者和同步副本" aria-label="Permalink to “領導者和同步副本”">​</a></h4><p>Kafka 在（由多個代理組成的）集羣中維護了多個分區。其中，負責維護分區的那個代理被稱為“<ruby>領導者<rt>leader</rt></ruby>”。只有領導者能夠在它的分區上接收和發送消息。</p><p>可是，萬一分區的領導者發生故障了，又該怎麼辦呢？為了確保業務連續性，每個領導者（代理）都會把它的分區複製到其他代理上。此時，這些其他代理就稱為該分區的<ruby>同步副本<rt>in-sync-replicas</rt></ruby>（ISR）。一旦分區的領導者發生故障，ZooKeeper 就會發起一次選舉，把選中的那個同步副本任命為新的領導者。此後，這個新的領導者將承擔該分區的消息接受和發送任務。管理員可以指定分區需要維護的同步副本的大小。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2021/09/Figure-3-Command-line-producer.jpg" alt="圖 3：生產者命令列工具"></p><h4 id="消息持久化" tabindex="-1">消息持久化 <a class="header-anchor" href="#消息持久化" aria-label="Permalink to “消息持久化”">​</a></h4><p>代理會將每個分區都映射到一個指定的磁盤文件，從而實現持久化。默認情況下，消息會在磁盤上保留一個星期。當消息寫入分區後，它們的內容和順序就不能更改了。管理員可以配置一些策略，如消息的保留時長、壓縮算法等。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2021/09/Figure-4-Command-line-consumer.jpg" alt="圖 4：消費者命令列工具"></p><h4 id="消費消息" tabindex="-1">消費消息 <a class="header-anchor" href="#消費消息" aria-label="Permalink to “消費消息”">​</a></h4><p>與大多數其他消息系統不同，Kafka 不會主動將消息發送給消費者。相反，消費者應該監聽主題，並主動讀取消息。一個消費者可以從某個主題的多個分區中讀取消息。多個消費者也可以讀取來自同一個分區的消息。Kafka 保證了同一條消息不會被同一個消費者重複讀取。</p><p>Kafka 中的每個消費者都有一個組 ID。那些組 ID 相同的消費者們共同組成了一個消費者組。通常，為了從 N 個主題分區讀取消息，管理員會創建一個包含 N 個消費者的消費者組。這樣一來，組內的每個消費者都可以從它的指定分區中讀取消息。如果組內的消費者比可用分區還要多，那麼多出來的消費者就會處於閒置狀態。</p><p>在任何情況下，Kafka 都保證：不管組內有多少個消費者，同一條消息只會被該消費者組讀取一次。這個架構提供了一致性、高性能、高可擴展性、準實時交付和消息持久性，以及零消息丟失。</p><h3 id="安裝、運行-kafka" tabindex="-1">安裝、運行 Kafka <a class="header-anchor" href="#安裝、運行-kafka" aria-label="Permalink to “安裝、運行 Kafka”">​</a></h3><p>儘管在理論上，Kafka 集羣可以由任意數量的代理組成，但在生產環境中，大多數集羣通常由三個或五個代理組成。</p><p>在這裏，我們將搭建一個單代理集羣，對於生產環境來説，它已經夠用了。</p>',31)),i("p",null,[a[1]||(a[1]=s("在瀏覽器中訪問 ",-1)),e(n,{href:"https://kafka.apache.org/downloads"},{default:p(()=>[...a[0]||(a[0]=[s("https://kafka.apache.org/downloads",-1)])]),_:1}),a[2]||(a[2]=s("，下載 Kafka 的最新版本。在 Linux 終端中，我們也可以使用下面的命令來下載它：",-1))]),a[19]||(a[19]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget https://www.apache.org/dyn/closer.cgi?path=/kafka/2.8.0/kafka_2.12-2.8.0.tgz</span></span></code></pre></div><p>如果需要的話，我們也可以把下載來的檔案文件 <code>kafka_2.12-2.8.0.tgz</code> 移動到另一個目錄下。解壓這個檔案，你會得到一個名為 <code>kafka_2.12-2.8.0</code> 的目錄，它就是之後我們要設置的 <code>KAFKA_HOME</code>。</p><p>打開 <code>KAFKA_HOME/config</code> 目錄下的 <code>server.properties</code> 文件，取消註釋下面這一行配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>listeners=PLAINTEXT://:9092</span></span></code></pre></div><p>這行配置的作用是讓 Kafka 在本機的 <code>9092</code> 端口接收普通文本消息。我們也可以配置 Kafka 通過<ruby>安全通道<rt>secure channel</rt></ruby>接收消息，在生產環境中，我們也推薦這麼做。</p><p>無論集羣中有多少個代理，Kafka 都需要 ZooKeeper 來管理和協調它們。即使是單代理集羣，也是如此。Kafka 在安裝時，會附帶安裝 ZooKeeper，因此，我們可以在 <code>KAFKA_HOME</code> 目錄下，在命令列中使用下面的命令來啓動它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./bin/zookeeper-server-start.sh ./config/zookeeper.properties</span></span></code></pre></div><p>當 ZooKeeper 運行起來後，我們就可以在另一個終端中啓動 Kafka 了，命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./bin/kafka-server-start.sh ./config/server.properties</span></span></code></pre></div><p>到這裏，一個單代理的 Kafka 集羣就運行起來了。</p><h3 id="驗證-kafka" tabindex="-1">驗證 Kafka <a class="header-anchor" href="#驗證-kafka" aria-label="Permalink to “驗證 Kafka”">​</a></h3><p>讓我們在 <code>topic-1</code> 主題上嘗試下發送和接收消息吧！我們可以使用下面的命令，在創建主題時為它指定分區的個數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./bin/kafka-topics.sh --create --topic topic-1 --zookeeper localhost:2181 --partitions 3 --replication-factor 1</span></span></code></pre></div><p>上述命令還同時指定了<ruby>複製因子<rt>replication factor</rt></ruby>，它的值不能大於集羣中代理的數量。我們使用的是單代理集羣，因此，複製因子只能設置為 1。</p><p>當主題創建完成後，生產者和消費者就可以在上面交換消息了。Kafka 的發行版內附帶了生產者和消費者的命令列工具，供測試時用。</p><p>打開第三個終端，運行下面的命令，啓動生產者：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./bin/kafka-console-producer.sh --broker-list localhost:9092 --topic topic-1</span></span></code></pre></div><p>上述命令顯示了一個提示符，我們可以在後面輸入簡單文本消息。由於我們指定的命令選項，生產者會把 <code>topic-1</code> 上的消息，發送到運行在本機的 9092 端口的 Kafka 中。</p><p>打開第四個終端，運行下面的命令，啓動消費者：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./bin/kafka-console-consumer.sh --bootstrap-server localhost:9092 --topic topic-1 –-from-beginning</span></span></code></pre></div><p>上述命令啓動了一個消費者，並指定它連接到本機 9092 端口的 Kafka。它訂閲了 <code>topic-1</code> 主題，以讀取其中的消息。由於命令列的最後一個選項，這個消費者會從最開頭的位置，開始讀取該主題的所有消息。</p><p>我們注意到，生產者和消費者連接的是同一個代理，訪問的是同一個主題，因此，消費者在收到消息後會把消息打印到終端上。</p><p>下面，讓我們在實際應用場景中，嘗試使用 Kafka 吧！</p><h3 id="案例" tabindex="-1">案例 <a class="header-anchor" href="#案例" aria-label="Permalink to “案例”">​</a></h3><p>假設有一家叫做 ABC 的公共汽車運輸公司，它擁有一支客運車隊，往返於全國不同城市之間。由於 ABC 希望實時跟蹤每輛客車，以提高其運營質量，因此，它提出了一個基於 Apache Kafka 的解決方案。</p><p>首先，ABC 公司為所有公交車都配備了位置追蹤設備。然後，它使用 Kafka 建立了一個操作中心，以接收來自數百輛客車的位置更新。它還開發了一個<ruby>儀表盤<rt>dashboard</rt></ruby>，以顯示任一時間點所有客車的當前位置。圖 5 展示了上述架構：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2021/09/Figure-5-Kafka-based-architecture.jpg" alt="圖 5：基於 Kafka 的架構"></p><p>在這種架構下，客車上的設備扮演了消息生產者的角色。它們會週期性地把當前位置發送到 Kafka 的 <code>abc-bus-location</code> 主題上。ABC 公司選擇以客車的<ruby>行程編號<rt>trip code</rt></ruby>作為消息鍵，以處理來自不同客車的消息。例如，對於從 Bengaluru 到 Hubballi 的客車，它的行程編號就會是 <code>BLRHL003</code>，那麼在這段旅程中，對於所有來自該客車的消息，它們的消息鍵都會是 <code>BLRHL003</code>。</p><p>儀表盤應用扮演了消息消費者的角色。它在代理上註冊了同一個主題 <code>abc-bus-location</code>。如此，這個主題就成為了生產者（客車）和消費者（儀表盤）之間的虛擬通道。</p><p>客車上的設備不會期待得到來自儀表盤應用的任何回覆。事實上，它們相互之間都不知道對方的存在。得益於這種架構，數百輛客車和操作中心之間實現了非阻塞通信。</p><h4 id="實現" tabindex="-1">實現 <a class="header-anchor" href="#實現" aria-label="Permalink to “實現”">​</a></h4><p>假設 ABC 公司想要創建三個分區來維護位置更新。由於我們的開發環境只有一個代理，因此複製因子應設置為 1。</p><p>相應地，以下命令創建了符合需求的主題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./bin/kafka-topics.sh --create --topic abc-bus-location --zookeeper localhost:2181 --partitions 3 --replication-factor 1</span></span></code></pre></div><p>生產者和消費者應用可以用多種語言編寫，如 Java、Scala、Python 和 JavaScript 等。下面幾節中的代碼展示了它們在 Java 中的編寫方式，好讓我們有一個初步瞭解。</p><h5 id="java-生產者" tabindex="-1">Java 生產者 <a class="header-anchor" href="#java-生產者" aria-label="Permalink to “Java 生產者”">​</a></h5><p>下面的 <code>Fleet</code> 類模擬了在 ABC 公司的 6 輛客車上運行的 Kafka 生產者應用。它會把位置更新發送到指定代理的 <code>abc-bus-location</code> 主題上。請注意，簡單起見，主題名稱、消息鍵、消息內容和代理地址等，都在代碼裏硬編碼的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public class Fleet {</span></span>
<span class="line"><span>    public static void main(String[] args) throws Exception {</span></span>
<span class="line"><span>        String broker = “localhost:9092”;</span></span>
<span class="line"><span>        Properties props = new Properties();</span></span>
<span class="line"><span>        props.setProperty(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, broker);</span></span>
<span class="line"><span>        props.setProperty(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,</span></span>
<span class="line"><span>            StringSerializer.class.getName());</span></span>
<span class="line"><span>        props.setProperty(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,</span></span>
<span class="line"><span>            StringSerializer.class.getName());</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        Producer&lt;String, String&gt; producer = new KafkaProducer&lt;String, String&gt;(props);</span></span>
<span class="line"><span>        String topic = “abc-bus-location”;</span></span>
<span class="line"><span>        Map&lt;String, String&gt; locations = new HashMap&lt;&gt;();</span></span>
<span class="line"><span>        locations.put(“BLRHBL001”, “13.071362, 77.461906”);</span></span>
<span class="line"><span>        locations.put(“BLRHBL002”, “14.399654, 76.045834”);</span></span>
<span class="line"><span>        locations.put(“BLRHBL003”, “15.183959, 75.137622”);</span></span>
<span class="line"><span>        locations.put(“BLRHBL004”, “13.659576, 76.944675”);</span></span>
<span class="line"><span>        locations.put(“BLRHBL005”, “12.981337, 77.596181”);</span></span>
<span class="line"><span>        locations.put(“BLRHBL006”, “13.024843, 77.546983”);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        IntStream.range(0, 10).forEach(i -&gt; {</span></span>
<span class="line"><span>            for (String trip : locations.keySet()) {</span></span>
<span class="line"><span>                ProducerRecord&lt;String, String&gt; record</span></span>
<span class="line"><span>                    = new ProducerRecord&lt;String, String&gt;(</span></span>
<span class="line"><span>                        topic, trip, locations.get(trip));</span></span>
<span class="line"><span>                producer.send(record);</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        });</span></span>
<span class="line"><span>        producer.flush();</span></span>
<span class="line"><span>        producer.close();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h5 id="java-消費者" tabindex="-1">Java 消費者 <a class="header-anchor" href="#java-消費者" aria-label="Permalink to “Java 消費者”">​</a></h5><p>下面的 <code>Dashboard</code> 類實現了一個 Kafka 消費者應用，運行在 ABC 公司的操作中心。它會監聽 <code>abc-bus-location</code> 主題，並且它的消費者組 ID 是 <code>abc-dashboard</code>。當收到消息後，它會立即顯示來自客車的詳細位置信息。我們本該配置這些詳細位置信息，但簡單起見，它們也是在代碼裏硬編碼的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public static void main(String[] args) {</span></span>
<span class="line"><span>    String broker = “127.0.0.1:9092”;</span></span>
<span class="line"><span>    String groupId = “abc-dashboard”;</span></span>
<span class="line"><span>    Properties props = new Properties();</span></span>
<span class="line"><span>    props.setProperty(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, broker);</span></span>
<span class="line"><span>    props.setProperty(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG,</span></span>
<span class="line"><span>        StringDeserializer.class.getName());</span></span>
<span class="line"><span>    props.setProperty(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,</span></span>
<span class="line"><span>        StringDeserializer.class.getName());</span></span>
<span class="line"><span>    props.setProperty(ConsumerConfig.GROUP_ID_CONFIG, groupId);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @SuppressWarnings(“resource”)</span></span>
<span class="line"><span>    Consumer&lt;String, String&gt; consumer = new KafkaConsumer&lt;String, String&gt;(props);</span></span>
<span class="line"><span>    consumer.subscribe(Arrays.asList(“abc-bus-location”));</span></span>
<span class="line"><span>    while (true) {</span></span>
<span class="line"><span>        ConsumerRecords&lt;String, String&gt; records</span></span>
<span class="line"><span>            = consumer.poll(Duration.ofMillis(1000));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        for (ConsumerRecord&lt;String, String&gt; record : records) {</span></span>
<span class="line"><span>            String topic = record.topic();</span></span>
<span class="line"><span>            int partition = record.partition();</span></span>
<span class="line"><span>            String key = record.key();</span></span>
<span class="line"><span>            String value = record.value();</span></span>
<span class="line"><span>            System.out.println(String.format(</span></span>
<span class="line"><span>                “Topic=%s, Partition=%d, Key=%s, Value=%s”,</span></span>
<span class="line"><span>                topic, partition, key, value));</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h5 id="依賴" tabindex="-1">依賴 <a class="header-anchor" href="#依賴" aria-label="Permalink to “依賴”">​</a></h5><p>為了編譯和運行這些代碼，我們需要 JDK 8 及以上版本。看到下面的 <code>pom.xml</code> 文件中的 Maven 依賴了嗎？它們會把所需的 Kafka 客户端庫下載並添加到類路徑中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>  &lt;groupId&gt;org.apache.kafka&lt;/groupId&gt;</span></span>
<span class="line"><span>  &lt;artifactId&gt;kafka-clients&lt;/artifactId&gt;</span></span>
<span class="line"><span>  &lt;version&gt;2.8.0&lt;/version&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span>
<span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>  &lt;groupId&gt;org.slf4j&lt;/groupId&gt;</span></span>
<span class="line"><span>  &lt;artifactId&gt;slf4j-simple&lt;/artifactId&gt;</span></span>
<span class="line"><span>  &lt;version&gt;1.7.25&lt;/version&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><h4 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to “部署”">​</a></h4><p>由於 <code>abc-bus-location</code> 主題在創建時指定了 3 個分區，我們自然就會想要運行 3 個消費者，來讓讀取位置更新的過程更快一些。為此，我們需要同時在 3 個不同的終端中運行儀表盤。因為所有這 3 個儀表盤都註冊在同一個組 ID 下，它們自然就構成了一個消費者組。Kafka 會為每個儀表盤都分配一個特定的分區（來消費）。</p><p>當所有儀表盤實例都運行起來後，在另一個終端中啓動 <code>Fleet</code> 類。圖 6、7、8 展示了儀表盤終端中的控制台示例輸出。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2021/09/Figure-6-Dashboard-Terminal-1.jpg" alt="圖 6：儀表盤終端之一"></p><p>仔細看看控制台消息，我們會發現第一個、第二個和第三個終端中的消費者，正在分別從 <code>partition-2</code>、<code>partition-1</code> 和 <code>partition-0</code> 中讀取消息。另外，我們還能發現，消息鍵為 <code>BLRHBL002</code>、<code>BLRHBL004</code> 和 <code>BLRHBL006</code> 的消息寫入了 <code>partition-2</code>，消息鍵為 <code>BLRHBL005</code> 的消息寫入了 <code>partition-1</code>，剩下的消息寫入了 <code>partition-0</code>。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2021/09/Figure-7-Dashboard-Terminal-2.jpg" alt="圖 7：儀表盤終端之二"></p><p>使用 Kafka 的好處在於，只要集羣設計得當，它就可以水平擴展，從而支持大量客車和數百萬條消息。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2021/09/Figure-8-Dashboard-Terminal-3.jpg" alt="圖 8：儀表盤終端之三"></p><h3 id="不止是消息" tabindex="-1">不止是消息 <a class="header-anchor" href="#不止是消息" aria-label="Permalink to “不止是消息”">​</a></h3><p>根據 Kafka 官網上的數據，在《財富》100 強企業中，超過 80% 都在使用 Kafka。它部署在許多垂直行業，如金融服務、娛樂等。雖然 Kafka 起初只是一種簡單的消息服務，但它已憑藉行業級的流處理能力，成為了大數據生態系統的一環。對於那些喜歡託管解決方案的企業，Confluent 提供了基於雲的 Kafka 服務，只需支付訂閲費即可。（LCTT 譯註：Confluent 是一個基於 Kafka 的商業公司，它提供的 Confluent Kafka 在 Apache Kafka 的基礎上，增加了許多企業級特性，被認為是“更完整的 Kafka”。）</p><hr>`,55)),i("p",null,[a[4]||(a[4]=s("via: ",-1)),e(n,{href:"https://www.opensourceforu.com/2021/11/apache-kafka-asynchronous-messaging-for-seamless-systems/"},{default:p(()=>[...a[3]||(a[3]=[s("https://www.opensourceforu.com/2021/11/apache-kafka-asynchronous-messaging-for-seamless-systems/",-1)])]),_:1})]),i("p",null,[a[9]||(a[9]=s("作者：",-1)),e(n,{href:"https://www.opensourceforu.com/author/krishna-mohan-koyya/"},{default:p(()=>[...a[5]||(a[5]=[s("Krishna Mohan Koyya",-1)])]),_:1}),a[10]||(a[10]=s(" 選題：",-1)),e(n,{href:"https://github.com/lkxed"},{default:p(()=>[...a[6]||(a[6]=[s("lkxed",-1)])]),_:1}),a[11]||(a[11]=s(" 譯者：",-1)),e(n,{href:"https://github.com/lkxed"},{default:p(()=>[...a[7]||(a[7]=[s("lkxed",-1)])]),_:1}),a[12]||(a[12]=s(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...a[8]||(a[8]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[15]||(a[15]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...a[13]||(a[13]=[s("LCTT",-1)])]),_:1}),a[16]||(a[16]=s(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...a[14]||(a[14]=[s("Linux中國",-1)])]),_:1}),a[17]||(a[17]=s(" 榮譽推出",-1))])])}const K=r(d,[["render",h]]);export{C as __pageData,K as default};
